changeSet.sql:
UPDATE static_section SET content = convert_to(replace(convert_from(content, 'UTF8'), 'Shom', 'SHN'), 'UTF8') WHERE content IS NOT NULL;
UPDATE static_section SET international_content = convert_to(replace(convert_from(international_content, 'UTF8'), 'Shom', 'SHN'), 'UTF8') WHERE international_content IS NOT NULL;

UPDATE static_page SET content = convert_to(replace(convert_from(content, 'UTF8'), 'Shom', 'SHN'), 'UTF8') WHERE content IS NOT NULL;
UPDATE static_page SET international_content = convert_to(replace(convert_from(international_content, 'UTF8'), 'Shom', 'SHN'), 'UTF8') WHERE international_content IS NOT NULL;
